//! Holder conformance tests against the reference fake authority.
//!
//! Fixtures are generated by `testkit` with published test keys. They stand
//! in for the authority's official golden vectors, which are not yet
//! available. The pull request description maps every vector.

mod apply_gate;
mod clock_hold;
mod core_only;
mod epoch;
mod list_client;
mod must_reject;
mod review_round2;
mod review_round3;
mod state_startup;

use crate::client::FetchFailure;
use crate::engine::EngineRefusal;
use crate::engine::{ArtifactStamp, CapabilityTimes, Cut, EngineQuery, RootObservation};
use crate::gate::Refusal;
use crate::holder::{ApplyReport, ListOutcome};
use crate::testkit::Rig;
use tempfile::TempDir;

/// Pinned kind under the neutral profile.
pub const PINNED: &str = "collection";
/// Accepted, unpinned kind under the neutral profile.
pub const PLAIN: &str = "archive";

pub fn rig() -> (TempDir, Rig) {
    let dir = tempfile::tempdir().expect("tempdir");
    let rig = Rig::new(&dir.path().join("holder"));
    (dir, rig)
}

#[track_caller]
pub fn applied(outcome: ListOutcome) -> ApplyReport {
    match outcome {
        ListOutcome::Applied(report) => report,
        other => panic!("expected an applied list, got {other:?}"),
    }
}

#[track_caller]
pub fn failed(outcome: ListOutcome) -> FetchFailure {
    match outcome {
        ListOutcome::Failed(failure) => failure,
        other => panic!("expected a failed list, got {other:?}"),
    }
}

/// The core check, for resources without a storage pin.
pub fn plain(rig: &Rig, id: &str) -> Result<(), Refusal> {
    rig.gate().check(id)
}

/// A pinned resource check with an artifact stamped `pin_ref` and a root
/// observation.
pub fn pinned(rig: &Rig, id: &str, pin_ref: &str, root: RootObservation) -> Result<(), Refusal> {
    rig.engine_gate().check(
        &EngineQuery {
            resource_id: id,
            capability: None,
            artifact: Some(ArtifactStamp {
                pin_ref,
                validated_under_matching_root: true,
            }),
            root,
        },
        Cut::Admission,
    )
}

/// A capability-authorized plain check at `cut`.
pub fn with_capability(
    rig: &Rig,
    id: &str,
    iat_s: i64,
    exp_s: i64,
    cut: Cut,
) -> Result<(), Refusal> {
    rig.engine_gate().check(
        &EngineQuery {
            resource_id: id,
            capability: Some(CapabilityTimes { iat_s, exp_s }),
            artifact: None,
            root: RootObservation::Unobserved,
        },
        cut,
    )
}

pub fn now_s(rig: &Rig) -> i64 {
    use crate::clock::Clock;
    rig.clock.wall_ms().div_euclid(1000)
}

pub fn codes(rig: &Rig) -> Vec<&'static str> {
    rig.events.codes()
}
